content.content:
40	            to->getName(),
41	            edge.backward ? "input" : "output",
42	            from->getName());
43	
44	    edge.to = it->second;
45	    auto & added_edge = edges.emplace_back(std::move(edge));
46	    added_edge.update_info.id = &added_edge;
47	    return added_edge;
48	}
