50	bool ExecutingGraph::addEdges(uint64_t node)
51	{
52	    IProcessor * from = nodes[node]->processor;
53	
54	    bool was_edge_added = false;
55	
56	    /// Add backward edges from input ports.
57	    auto & inputs = from->getInputs();
58	    auto from_input = nodes[node]->back_edges.size();
59	
60	    if (from_input < inputs.size())
61	    {
62	        was_edge_added = true;
63	
64	        for (auto it = std::next(inputs.begin(), from_input); it != inputs.end(); ++it, ++from_input)
65	        {
66	            const IProcessor * to = &it->getOutputPort().getProcessor();
67	            auto output_port_number = to->getOutputPortNumber(&it->getOutputPort());
68	            Edge edge(0, true, from_input, output_port_number, &nodes[node]->post_updated_input_ports);
69	            auto & added_edge = addEdge(nodes[node]->back_edges, std::move(edge), from, to);
70	            it->setUpdateInfo(&added_edge.update_info);
71	        }
72	    }
73	
74	    /// Add direct edges form output ports.
75	    auto & outputs = from->getOutputs();
76	    auto from_output = nodes[node]->direct_edges.size();
77	
78	    if (from_output < outputs.size())
79	    {
80	        was_edge_added = true;
81	
82	        for (auto it = std::next(outputs.begin(), from_output); it != outputs.end(); ++it, ++from_output)
83	        {
84	            const IProcessor * to = &it->getInputPort().getProcessor();
85	            auto input_port_number = to->getInputPortNumber(&it->getInputPort());
86	            Edge edge(0, false, input_port_number, from_output, &nodes[node]->post_updated_output_ports);
87	            auto & added_edge = addEdge(nodes[node]->direct_edges, std::move(edge), from, to);
88	            it->setUpdateInfo(&added_edge.update_info);
89	        }
90	    }
91	
92	    return was_edge_added;
93	}
